<template>
  <div>
    <div class="container-fluid" v-if="hasContent">
      <div>
        <div style="text-align: left; float: left">
          <span style="color: green; font-size: 18px; font-weight: bold"
            >查詢結果</span
          >
        </div>

        <div style="text-align: right">
          <span style="font-weight: bold">共 {{ total }} 筆資料</span>
        </div>
      </div>

      <br />
      <b-table
        :items="content.items"
        :fields="content.fields"
        head-variant="primary"
        hover
        class="table-responsive"
        style="text-align: center"
      >
      </b-table>
    </div>

    <div v-if="!hasContent"></div>
  </div>
</template>

<script>
import { reactive, onMounted, ref } from "vue";
import { BTable } from "bootstrap-vue-next";
import { useRoute } from "vue-router";
// import axios from "axios";
import axios from "@/axios/http";

export default {
  name: "single-query-taskId",
  props: {},
  components: {
    BTable,
  },
  setup() {
    const route = useRoute();

    const hasContent = ref(false);

    //init '' or 0
    const total = ref(0);

    const content = reactive({
      fields: [
        { key: "origrinalAddress", label: "原地址" },
        { key: "fullAddress", label: "標準地址" },
        { key: "addressId", label: "地址編碼" },
        { key: "location", label: "經緯度" },
        { key: "joinStep", label: "比對代碼" },
      ],
      items: [],
    });

    onMounted(async () => {
      let qrcodeData = sessionStorage.getItem("qrcodeData");
      if (qrcodeData == null) {
        await findbySeq();
        total.value = content.items.length;
        hasContent.value = true;
      } else {
        let items = JSON.parse(sessionStorage.getItem("qrcodeData"));
        content.items = items;
        console.log("items:", items);
        console.log("content:", content);
        total.value = content.items.length;
        hasContent.value = true;
      }
    });

    function isNullorEmpty(str) {
      if (str == null || str == "") {
        return true;
      }
    }

    function findbySeq() {
      //從queryString 上取出token
      let taskId = "";
      let joinStep = "";
      let origrinalAddress = "";
      if (!isNullorEmpty(route)) {
        let keysArray = Object.keys(route.query);
        let keys = ["taskId", "origrinalAddress", "joinStep"];
        keys.forEach((key) => {
          if (isNullorEmpty(keysArray[key])) {
            return;
          }
        });
        // if (keysArray.includes("taskId")) {
        taskId = route.query.taskId;
        origrinalAddress = route.query.origrinalAddress;
        joinStep = route.query.joinStep;
        console.log("taskId:", taskId);
        // }
      }

      //從queryString 上取出token，作為標頭發送請求至AP
      axios
        .post("/singlequery/qrcode-data", {
          taskId: taskId,
          origrinalAddress: origrinalAddress,
          joinStep: joinStep,
        })
        .then((res) => {
          //AP 返回token封包的seqs至DB查詢後的資料。
          if (!isNullorEmpty(res)) {
            // content.items = res.data;
            content.items.splice(0, content.items.length, ...res);
          }
        })
        .finally(() => {
          sessionStorage.setItem("qrcodeData", JSON.stringify(content.items));
        });
    }

    return {
      hasContent,
      total,
      content,
    };
  },
};
</script>

