import { createRouter, createWebHistory } from '../../../../../node_modules/vue-router';
// import App from '../App';
// import HelloWorld from '../components/HelloWorld';
import singleQuery from '../components/single-query';
import singleQueryToken from '../components/single-query-token';
import singleQueryTaskId from '../components/single-query-taskId';



const routes = [
// 不要加context.prefix
  {
    path: '/single-query',
    name: 'singleQuery',
    component: singleQuery
  }, 
  {
    path: '/single-query-token',
    name: 'singleQueryToken',
    component: singleQueryToken
  }, 
  {
    path: '/single-query-taskId',
    name: 'singleQueryTaskId',
    component: singleQueryTaskId
  }, 
  // 其他路由配置
];

const router = createRouter({
  history: createWebHistory(process.env.BASE_URL),
  routes
});

export default router;