import axios from 'axios';


const apiBasePath = process.env.NODE_ENV === 'production' ? '/iisi/api' : '/api';


// 自訂axios
const instance = axios.create({
  baseURL: apiBasePath, //前綴 proxy在vue.config.js
  timeout: 10000, 
  headers: {
    'Content-Type': 'application/json'
  }
});

//請求攔截器
instance.interceptors.request.use(
  config => {
    // 請求發送前
    // config.headers['Authorization'] = 'Bearer your-token-here';
    return config;
  },
  error => {
    // 請求錯誤
    return Promise.reject(error);
  }
);

// 攔截響應
instance.interceptors.response.use(
  response => {
    return response.data;
  },
  error => {
    if (error.response && error.response.status === 404) {
      // 如果是404 要做什麼回覆
      return Promise.reject(new Error('Resource not found (404)'));
    }
    // 其他錯誤繼續拋出
    return Promise.reject(error);
  }
);

export default instance;
